html:
{#- The job ticket that travels with a run. Its barcode is the works order number, which the
    Print Floor opens at the step whose turn it is. fp_barcode is this app's Jinja method. -#}
{%- set customer = frappe.db.get_value("Sales Order", doc.sales_order, "customer_name") if doc.sales_order else "" -%}
<style>
.fp-ticket { font-size: 11pt; color: #000; }
.fp-ticket h1 { font-size: 18pt; margin: 0 0 4mm; }
.fp-ticket .code svg { display: block; width: 95mm; height: 18mm; }
.fp-ticket .number { font-family: monospace; font-size: 15pt; font-weight: 700; letter-spacing: 0.08em; margin: 1mm 0 5mm; }
.fp-ticket table { width: 100%; border-collapse: collapse; }
.fp-ticket .facts td { padding: 1.2mm 3mm 1.2mm 0; vertical-align: top; }
.fp-ticket .facts td.label { color: #555; width: 22mm; }
.fp-ticket .steps { margin-top: 6mm; }
.fp-ticket .steps th, .fp-ticket .steps td { border: 1px solid #333; padding: 3mm 2.5mm; text-align: left; }
.fp-ticket .steps th { background: #eee; }
.fp-ticket .hint { margin-top: 4mm; color: #555; font-size: 9pt; }
</style>
<div class="fp-ticket">
	<h1>Job Ticket</h1>
	<div class="code">{{ fp_barcode(doc.name) }}</div>
	<div class="number">{{ doc.name }}</div>
	<table class="facts">
		<tr><td class="label">Customer</td><td><b>{{ customer or "For stock" }}</b></td>
			<td class="label">Order</td><td>{{ doc.sales_order or "" }}</td></tr>
		<tr><td class="label">Product</td><td colspan="3"><b>{{ doc.production_item }}</b> {{ doc.item_name }}</td></tr>
		<tr><td class="label">Run</td><td><b>{{ "{:,.0f}".format(doc.qty or 0) }}</b> {{ doc.stock_uom }}</td>
			<td class="label">Planned</td><td>{{ doc.get_formatted("planned_start_date") }}</td></tr>
	</table>
	<table class="steps">
		<thead><tr><th>#</th><th>Step</th><th>Workstation</th><th>Planned min</th><th>Good</th><th>Spoiled</th><th>Initials</th></tr></thead>
		<tbody>
		{%- for op in doc.operations %}
			<tr><td>{{ op.sequence_id or loop.index }}</td><td>{{ op.operation }}</td><td>{{ op.workstation }}</td>
				<td>{{ "{:,.0f}".format(op.time_in_mins or 0) }}</td><td></td><td></td><td></td></tr>
		{%- endfor %}
		</tbody>
	</table>
	<p class="hint">Scan this ticket at each step on the Print Floor. The blank columns are for when the screen is down.</p>
</div>
